#include "awt/image/jxx.awt.image.FilteredImageSource.h"
#include "awt/image/jxx.awt.image.ImageFilter.h"
namespace jxx::awt::image{FilteredImageSource::FilteredImageSource(const ::jxx::Ptr<ImageProducer>&s,const ::jxx::Ptr<ImageFilter>&f):source_(s),filter_(f){}void FilteredImageSource::addConsumer(const ::jxx::Ptr<ImageConsumer>&c){if(source_&&filter_)source_->addConsumer(filter_->getFilterInstance(c));}bool FilteredImageSource::isConsumer(const ::jxx::Ptr<ImageConsumer>&){return false;}void FilteredImageSource::removeConsumer(const ::jxx::Ptr<ImageConsumer>&){}void FilteredImageSource::startProduction(const ::jxx::Ptr<ImageConsumer>&c){if(source_&&filter_)source_->startProduction(filter_->getFilterInstance(c));}void FilteredImageSource::requestTopDownLeftRightResend(const ::jxx::Ptr<ImageConsumer>&c){startProduction(c);}}
